using System;using System.Text;using System.Collections.Generic;using System.Globalization;
namespace OsuLegacy {
 // Bounded JSON reader for public mirror responses; no reflection or dynamic code.
 public sealed class MirrorJson {
  private readonly string text;private int position,nodes;private MirrorJson(string value){if(value==null || value.Length>2*1024*1024)throw new FormatException("Mirror response is too large");text=value;}
  public static object Parse(string text){var reader=new MirrorJson(text);object result=reader.Value(0);reader.Space();if(reader.position!=text.Length)throw new FormatException("Unexpected data after JSON");return result;}
  private void Space(){while(position<text.Length && (text[position]==' '||text[position]=='\r'||text[position]=='\n'||text[position]=='\t'))position++;}
  private bool Take(char c){Space();if(position<text.Length && text[position]==c){position++;return true;}return false;}
  private object Value(int depth){if(depth>24 || ++nodes>100000)throw new FormatException("Mirror JSON is too complex");Space();if(position>=text.Length)throw new FormatException("Incomplete JSON");char c=text[position];if(c=='"')return String();if(c=='{'){position++;var result=new Dictionary<string,object>(StringComparer.Ordinal);if(Take('}'))return result;do{Space();if(position>=text.Length || text[position]!='"')throw new FormatException("Invalid JSON key");string key=String();if(!Take(':'))throw new FormatException("Missing JSON colon");result[key]=Value(depth+1);}while(Take(','));if(!Take('}'))throw new FormatException("Incomplete JSON object");return result;}if(c=='['){position++;var result=new List<object>();if(Take(']'))return result;do{result.Add(Value(depth+1));}while(Take(','));if(!Take(']'))throw new FormatException("Incomplete JSON array");return result;}
   if(c=='t' || c=='f' || c=='n'){string literal=c=='t'?"true":c=='f'?"false":"null";if(position+literal.Length>text.Length || text.Substring(position,literal.Length)!=literal)throw new FormatException("Invalid JSON literal");position+=literal.Length;return c=='n'?null:(object)(c=='t');}
   int start=position;if(text[position]=='-')position++;if(position>=text.Length)throw new FormatException("Invalid number");if(text[position]=='0')position++;else {int digits=position;while(position<text.Length && text[position]>='0' && text[position]<='9')position++;if(position==digits)throw new FormatException("Invalid number");}if(position<text.Length && text[position]=='.'){position++;int digits=position;while(position<text.Length && Char.IsDigit(text[position]))position++;if(position==digits)throw new FormatException("Invalid fraction");}if(position<text.Length && (text[position]=='e'||text[position]=='E')){position++;if(position<text.Length && (text[position]=='+'||text[position]=='-'))position++;int digits=position;while(position<text.Length && Char.IsDigit(text[position]))position++;if(digits==position)throw new FormatException("Invalid exponent");}double n;if(!double.TryParse(text.Substring(start,position-start),NumberStyles.Float,CultureInfo.InvariantCulture,out n)||Double.IsNaN(n)||Double.IsInfinity(n))throw new FormatException("Invalid number");return n;
  }
  private string String(){position++;var result=new StringBuilder();while(position<text.Length){char c=text[position++];if(c=='"')return result.ToString();if(c<' ')throw new FormatException("Invalid JSON string");if(c=='\\'){if(position>=text.Length)break;c=text[position++];switch(c){case '"':case '\\':case '/':break;case 'b':c='\b';break;case 'f':c='\f';break;case 'n':c='\n';break;case 'r':c='\r';break;case 't':c='\t';break;case 'u':if(position+4>text.Length)throw new FormatException("Invalid Unicode escape");int value;if(!int.TryParse(text.Substring(position,4),NumberStyles.HexNumber,CultureInfo.InvariantCulture,out value))throw new FormatException("Invalid Unicode escape");position+=4;c=(char)value;break;default:throw new FormatException("Invalid escape");}}result.Append(c);if(result.Length>65536)throw new FormatException("JSON string too long");}throw new FormatException("Incomplete JSON string");}
 }
 public sealed class MirrorDifficulty {public int Id,Mode,Length;public string Name;public double Stars,AR,OD,CS,HP;}
 public sealed class MirrorSet {
  public int Id,Status;public string Title,Artist,Creator,Updated;public bool Video;public readonly List<MirrorDifficulty> Difficulties=new List<MirrorDifficulty>();public string CoverPath;
  public double MinStars{get{double n=1000;foreach(var d in Difficulties)n=Math.Min(n,d.Stars);return n==1000?0:n;}}public double MaxStars{get{double n=0;foreach(var d in Difficulties)n=Math.Max(n,d.Stars);return n;}}
  public static string Text(Dictionary<string,object> o,string key,string fallback){object v;return o.TryGetValue(key,out v) && v is string?Clean((string)v):fallback;}
  private static string Clean(string text){return text.Replace('\r',' ').Replace('\n',' ').Replace('\t',' ');}
  public static double Number(Dictionary<string,object> o,string key,double fallback){object v;if(!o.TryGetValue(key,out v))return fallback;if(v is bool)return (bool)v?1:0;if(v is double)return (double)v;double n;return v is string && double.TryParse((string)v,NumberStyles.Float,CultureInfo.InvariantCulture,out n) && !Double.IsNaN(n)&&!Double.IsInfinity(n)?n:fallback;}
  public static List<MirrorSet> Parse(string json){var array=MirrorJson.Parse(json) as List<object>;if(array==null)throw new FormatException("Hinamizawa did not return a beatmap list");if(array.Count>100)throw new FormatException("Mirror returned too many sets");var result=new List<MirrorSet>();var seen=new Dictionary<int,bool>();foreach(object item in array){var row=item as Dictionary<string,object>;if(row==null)continue;double id=Number(row,"SetID",0);if(id<1 || id>int.MaxValue || id!=Math.Floor(id) || seen.ContainsKey((int)id))continue;seen[(int)id]=true;var set=new MirrorSet {Id=(int)id,Title=Text(row,"Title","Untitled"),Artist=Text(row,"Artist","Unknown artist"),Creator=Text(row,"Creator","Unknown mapper"),Updated=Text(row,"LastUpdate",""),Status=(int)Number(row,"RankedStatus",0),Video=Number(row,"HasVideo",0)!=0};object children;if(row.TryGetValue("ChildrenBeatmaps",out children) && children is List<object>)foreach(object child in (List<object>)children){if(set.Difficulties.Count>=256)break;var d=child as Dictionary<string,object>;if(d==null)continue;double bid=Number(d,"BeatmapID",0),mode=Number(d,"Mode",-1);if(bid<1 || bid>int.MaxValue || mode<0 || mode>3)continue;set.Difficulties.Add(new MirrorDifficulty{Id=(int)bid,Mode=(int)mode,Name=Text(d,"DiffName","Unknown difficulty"),Stars=Math.Max(0,Math.Min(100,Number(d,"DifficultyRating",0))),Length=(int)Math.Max(0,Math.Min(86400,Number(d,"TotalLength",0))),AR=Number(d,"AR",0),OD=Number(d,"OD",0),CS=Number(d,"CS",0),HP=Number(d,"HP",0)});}set.Difficulties.Sort(delegate(MirrorDifficulty a,MirrorDifficulty b){int m=a.Mode.CompareTo(b.Mode);return m!=0?m:a.Stars.CompareTo(b.Stars);});result.Add(set);}return result;}
 }
 public sealed class MirrorQuery {
  public string Text="",Genre="",Language="";public int Mode=-1,Status=1,Sort;public double MinStars,MaxStars=100;public const int PageSize=12;
  public string Path(int offset){if(offset<0 || offset>100000)throw new ArgumentOutOfRangeException("offset");string[] sort={"ranked_desc","plays_desc","favourites_desc","title_asc","artist_asc"};return "/api/v1/hinai/search?query="+Encode(Text)+"&amount="+PageSize+"&offset="+offset+"&mode="+Math.Max(-1,Math.Min(3,Mode))+ (Status>=0?"&status="+Math.Min(4,Status):"")+"&sort="+sort[Math.Max(0,Math.Min(sort.Length-1,Sort))]+"&min_stars="+MinStars.ToString("0.##",CultureInfo.InvariantCulture)+"&max_stars="+MaxStars.ToString("0.##",CultureInfo.InvariantCulture)+"&explicit=hide"+(Genre!=""?"&genre="+Encode(Genre):"")+(Language!=""?"&language="+Encode(Language):"");}
  public static string Encode(string value){byte[] bytes=Encoding.UTF8.GetBytes(value??"");var text=new StringBuilder();foreach(byte b in bytes){if(b>=65&&b<=90 || b>=97&&b<=122 || b>=48&&b<=57 || b==45||b==95||b==46||b==126)text.Append((char)b);else{text.Append('%');text.Append(b.ToString("X2"));}}return text.ToString();}
 }
}
